      "@type": "FAQPage",
      "@id": "https://www.hamlettrenovations.com/#faq",
      "isPartOf": {
        "@id": "https://www.hamlettrenovations.com/#webpage"
      },
      "mainEntity": [
        {
          "@type": "Question",
          "name": "How much will my remodel cost?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "It depends on size, materials, and scope. A kitchen refresh that keeps the layout runs $35,000 to $60,000; a full design-build kitchen runs $60,000 to $140,000. A bathroom refresh that keeps the layout runs $12,000 to $22,000; a full design-build bathroom runs $22,000 to $40,000. Where the layout is changing, the design phase comes first - from $5,000 for kitchens, credited toward your construction contract - and we price the build against the design you approve, so the number reflects something real rather than a guess."
          }
        },
        {
          "@type": "Question",
          "name": "Do you offer financing?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. We'll walk you through the options at your consultation. Terms depend on project amount, lender and credit approval."
          }
        },
        {
          "@type": "Question",
          "name": "How long does a project take?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Design usually runs three to five weeks depending on rounds of changes. Construction depends on whether the layout moves: a refresh runs three to six weeks, and a full design-build kitchen runs ten to fourteen weeks."
          }
        },
        {
          "@type": "Question",
          "name": "Are you licensed and insured?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes — licensed NJ Home Improvement Contractor (NJ HIC #13VH12093400) and fully insured. Every project is backed by a 1-year workmanship warranty."
          }
        },
        {
          "@type": "Question",
          "name": "Do you handle permits?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. We pull the permits and schedule inspections so your project is done to code."
          }
        },
        {
          "@type": "Question",
          "name": "What areas do you serve?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "We're based in Wayne and build across four North Jersey counties. In Bergen: Franklin Lakes, Wyckoff, Oakland, Ridgewood, Ho-Ho-Kus, Glen Rock, Midland Park, Allendale, Saddle River, Mahwah and Paramus. In Passaic: Wayne, North Haledon, Hawthorne, Woodland Park, Totowa, Little Falls, Pompton Lakes and Clifton. In Morris: Pequannock, Lincoln Park, Kinnelon, Montville, Boonton, Parsippany and Morristown. In Essex: Fairfield, Cedar Grove, the Caldwells, Verona, Roseland, Montclair and Livingston. If your town isn't on the list, just ask — we'll tell you honestly whether we cover it."
          }
        }
      ]
    }
