      "@id": "https://www.hamlettrenovations.com/home-additions#service",
      "serviceType": "Home Additions",
      "name": "Home Additions",
      "provider": {
        "@id": "https://www.hamlettrenovations.com/#business"
      },
      "areaServed": [
        {
          "@type": "AdministrativeArea",
          "name": "Bergen County, NJ"
        },
        {
          "@type": "AdministrativeArea",
          "name": "Passaic County, NJ"
        },
        {
          "@type": "AdministrativeArea",
          "name": "Morris County, NJ"
        },
